//!Typed seeded reader stages, with real Game destruction/restore and shared
//!pools. These are not asserted natural browser-command/job-birth histories.
use super::*;const BUILD:u32=0x5c5e38;
fn mission()->Value{let n=4096;let mut rows=Vec::new();for i in 0..35{let mut disk=vec![0u8;80];disk[..2].copy_from_slice(&(-1i16).to_le_bytes());disk[2..4].copy_from_slice(&(-1i16).to_le_bytes());disk[4]=255;if i==0{for(at,v)in[(0,100i16),(2,100),(26,100),(28,100),(73,-1)]{disk[at..at+2].copy_from_slice(&v.to_le_bytes());}disk[4]=0;}rows.push(json!({"nativeSlot":i,"kind":if i==0{0}else{-1},"x":if i==0{100}else{-1},"y":if i==0{100}else{-1},"hp":if i==0{100}else{-1},"maxHp":100,"flags6":0,"nativeDisk80":disk,"buildingId":if i==0{Some(10)}else{None}}));}json!({"map":{"width":64,"height":64,"tileSize":32,"world":0,"original":true,"seed":49,"revision":0,"tiles":vec![0;n],"terrainCodes":vec![0;n],"nativeTerrainPlane":vec![0;16384],"nativeRoadGraph":{"regions":[]},"originalTiles":vec![0;n],"territory":vec![0;n],"bridgeBase":vec![-1;n],"bridgeHp":[0],"bridgeMaxHp":[600]},"sectors":[],"spawns":[],"crates":[],"originalObjects":[],"walls":[],"buildings":[{"id":10,"kind":"repair","team":0,"sector":0,"x":200,"y":200,"w":160,"h":128,"hp":100,"maxHp":100,"stars":0,"product":null,"progress":0}],"nativeWorldBuildings":rows,"nativeBuildingFragments":[{"nativeSlot":0,"templates":[[0,0,250,1,1,1],[-1,0,0,0,0,0]]}],"bridges":[{"id":0,"nativeSlot":0,"nativeOrientation":0,"x":1000,"y":200,"w":288,"h":128,"hp":0,"maxHp":600,"nativeFlags15":2}]})}
fn view(g:&mut Game,host:[i16;2],guest:[i16;2],masters:[bool;2]){g.set_native_listener_settings(&json!({"0":{"soundEnabled":masters[0],"view":{"camera":host,"size":[320,240]},"hardwareContext":"1:0"},"1":{"soundEnabled":masters[1],"view":{"camera":guest,"size":[320,240]},"hardwareContext":"1:0"}}));}
fn field()->Game{let mut g=Game::new(0,1,49);g.map.original=true;g.multiplayer=true;g.apply_original(&mission()).unwrap();g.ai_teams.clear();g.native_view=Some(([0,0],[1024,1024]));g.native_feedback.ui_clock=500;view(&mut g,[0,0],[400,0],[true,true]);g.native_blast_environment(84,84,255,255,false);assert_eq!(g.native_world.as_ref().unwrap().buildings[0].record.hp,0);g.events.clear();g.native_audio=Default::default();g.native_listener_audio.guest_audio=Default::default();g}
fn jobs(g:&mut Game,frame:u8){let s=g.native_world.as_mut().unwrap();let h=trail::header(0).unwrap().0;s.trail.put_word(h,1).unwrap();s.trail.write(h+10,&[9,8]).unwrap();let bridge=0x647210;s.trail.bridge_headers=vec![(bridge,vec![0;1280])];s.trail.put_word(bridge,129).unwrap();s.trail.write(bridge+10,&[9,8]).unwrap();let b=&mut s.bridges[0];b.record.hp=601;b.raw_tail[16]=2;b.record.flags15=0x2e;for(i,(header,target))in[(h,BUILD),(bridge,super::crane_bridge::BASE),(bridge,super::crane_bridge::BASE)].into_iter().enumerate(){let j=&mut s.trail.jobs[i];j.set_ptr(0,header);j.set_ptr(4,target);j.0[12]=frame;j.set(20,0);}g.map.bridge_hp[0]=601.;}
fn samples(g:&Game)->Vec<(u64,u64)>{g.events.iter().filter(|e|e["kind"]=="nativeSample").map(|e|(e["sampleId"].as_u64().unwrap(),e["recipientTeam"].as_u64().unwrap_or(0))).collect()}
fn world(g:&Game)->Value{let s=g.native_world.as_ref().unwrap();json!({"map":g.map,"buildings":g.buildings,"records":s.buildings.iter().map(|b|(b.record.position,b.record.kind,b.record.hp,b.maximum)).collect::<Vec<_>>(),"bridge":s.bridges.iter().map(|b|b.raw().to_vec()).collect::<Vec<_>>(),"rawBuilds":s.trail.builds.iter().map(|b|b.to_vec()).collect::<Vec<_>>(),"jobs":s.trail.jobs.iter().map(|j|j.0.to_vec()).collect::<Vec<_>>(),"arena":s.trail.arena,"headers":s.trail.bridge_headers,"fragments":s.fragments.pools.iter().map(|p|p.records.iter().map(|r|r.bytes.to_vec()).collect::<Vec<_>>()).collect::<Vec<_>>(),"fx":s.effects.iter().map(|p|p.as_ref().map(|p|p.bytes().to_vec())).collect::<Vec<_>>(),"rng":g.original_rng.words,"crt":g.native_cosmetic_rng})}
#[test]fn late_build_game_mixed_real_restore_final_bridge_and_rng_are_once_per_world(){let mut reference=None;for masters in[[true,true],[false,true],[true,false],[false,false]]{for swap in[false,true]{let mut g=field();let(a,b)=if swap{([400,0],[0,0])}else{([0,0],[400,0])};view(&mut g,a,b,masters);jobs(&mut g,2);g.original_rng.multiplayer=true;let before=g.original_rng.words;g.update_native_building_trails(0);let now=world(&g);if let Some(expected)=&reference{assert_eq!(&now,expected);}else{reference=Some(now);}let s=g.native_world.as_ref().unwrap();assert_eq!((s.buildings[0].record.hp,s.bridges[0].record.hp,s.bridges[0].raw_tail[16]),(100,600,0));assert!(s.trail.jobs[..3].iter().all(|j|j.ptr(0)==0));assert_eq!(g.original_rng.words,before,"MP random leaf returns zero without a second world pass");assert_eq!(samples(&g),(if swap{[1usize,0]}else{[0,1]}).into_iter().filter(|&i|masters[i]).map(|i|(46,i as u64)).collect::<Vec<_>>());assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(99,99));assert_eq!((g.native_audio.effect_counter,g.native_listener_audio.guest_audio.effect_counter),(i16::from(masters[0]),i16::from(masters[1])));assert!(g.events.iter().filter(|e|e["kind"]=="nativeSample").all(|e|e["nativeHardwareAudioContext"]=="1:0"));}}}
#[test]fn late_build_game_frame7_consumes_muted_chances_and_does_not_share_exp_gate(){let mut g=field();jobs(&mut g,8);view(&mut g,[0,0],[400,0],[false,true]);g.native_audio.opportunity_gate=255;g.native_listener_audio.guest_audio.opportunity_gate=1;g.native_audio.explosion_cycle=7;g.update_native_building_trails(0);assert_eq!(samples(&g),[(44,1)]);assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(99,99));assert_eq!((g.native_audio.opportunity_gate,g.native_listener_audio.guest_audio.opportunity_gate,g.native_audio.explosion_cycle),(255,1,7));assert_eq!(g.native_world.as_ref().unwrap().bridges[0].raw_tail[16],2);}
#[test]fn late_build_game_unknown_restore_cannot_emit_premature46_or_repeat_world_rng(){let mut g=field();g.multiplayer=false;jobs(&mut g,2);g.native_world.as_mut().unwrap().trail.jobs[1].set_ptr(0,0);g.native_world.as_mut().unwrap().trail.jobs[2].set_ptr(0,0);g.native_world.as_mut().unwrap().fragments.bindings[0]=None;g.native_audio.late_build_clock=7;let mut expected=g.original_rng.clone();expected.multiplayer=false;expected.next_u32();g.update_native_building_trails(0);assert!(samples(&g).is_empty(),"46 belongs AFTER a known completed450260 restore");assert_eq!(g.native_audio.late_build_clock,6);assert_eq!(g.original_rng.words,expected.words,"known constructor prefix is once before the unavailable fragment pointer");assert_eq!(g.native_world.as_ref().unwrap().buildings[0].record.hp,0);}
#[test]fn late_build_game_missing_current_target_is_not_a_bbox_or_old_anchor_fallback(){let mut g=field();jobs(&mut g,8);for j in &mut g.native_world.as_mut().unwrap().trail.jobs[1..3]{j.set_ptr(0,0);}g.native_world.as_mut().unwrap().trail.jobs[0].set_ptr(4,BUILD+1);g.update_native_building_trails(0);assert!(samples(&g).is_empty());assert_eq!(g.native_world.as_ref().unwrap().trail.boundary,Some(trail::Boundary{address:BUILD+1,length:88}));}
#[test]fn late_build_game_apply_resets_both_listeners_but_import_ui_settings_and_skipped_reader_do_not(){for mp in[false,true]{let mut g=field();g.multiplayer=mp;g.native_audio.late_build_clock=u32::MAX;g.native_listener_audio.guest_audio.late_build_clock=100;g.native_audio.explosion_cycle=7;g.native_listener_audio.guest_audio.explosion_cycle=3;g.import_native_world(&mission());view(&mut g,[400,0],[0,0],[true,false]);for _ in 0..12{g.step_native_ui_only(1./17.);}g.update_native_building_trails(1);assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(u32::MAX,100));g.apply_original(&mission()).unwrap();assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(0,0));assert_eq!((g.native_audio.explosion_cycle,g.native_listener_audio.guest_audio.explosion_cycle),(7,3));}}
#[test]fn late_build_game_empty_missing_view_reader_decrements_each_existing_timer_once(){let mut g=field();g.native_world.as_mut().unwrap().trail.jobs.fill(trail::Job([0;24]));g.set_native_listener_settings(&json!({"1":{"soundEnabled":true}}));g.native_audio.late_build_clock=100;g.native_listener_audio.guest_audio.late_build_clock=0x80000000;let before=world(&g);g.update_native_building_trails(0);assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(99,0x7fffffff));assert_eq!(world(&g),before);assert!(samples(&g).is_empty());}
#[test]fn late_build_game_sp_full_restore_spends_the_real_constructor_rng_once(){let mut g=field();g.multiplayer=false;jobs(&mut g,2);let mut expected=g.original_rng.clone();expected.multiplayer=false;expected.next_u32();g.update_native_building_trails(0);assert_eq!(g.original_rng.words,expected.words);assert_eq!(g.native_world.as_ref().unwrap().buildings[0].record.hp,100);assert_eq!(samples(&g),[(46,0)]);assert_eq!((g.native_audio.late_build_clock,g.native_audio.effect_counter),(99,1));}
#[test]fn late_build_game_owner4_bridge_reentry_and_late_reader_use_separate_local_timers(){let mut reference=None;for muted in[false,true]{let mut g=field();view(&mut g,[0,0],[400,0],[!muted,!muted]);g.map.bridge_hp[0]=1.;{let s=g.native_world.as_mut().unwrap();s.bridges[0].record.hp=1;s.bridges[0].record.flags15=0;s.last_projection=[160,100];let mut raw=[0;44];raw[..2].copy_from_slice(&1i16.to_le_bytes());raw[6..8].copy_from_slice(&328i16.to_le_bytes());raw[8..10].copy_from_slice(&(-12i16).to_le_bytes());raw[26..28].copy_from_slice(&1138i16.to_le_bytes());s.put_effect(400,effects::Particle::from_bytes(raw));}g.set_world_code(7*128+32,23);g.finish_native_building_part_expiry(400,effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});assert_eq!(g.map.bridge_hp[0],0.);assert_eq!(g.native_listener_audio.guest_audio.opportunity_gate,1);jobs(&mut g,8);g.update_native_building_trails(0);let state=world(&g);if let Some(before)=&reference{assert_eq!(&state,before);}else{reference=Some(state);}assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(99,99));assert_eq!(samples(&g),if muted{vec![]}else{vec![(1,1),(44,0),(44,1)]});assert!(g.native_world.as_ref().unwrap().effects[400].as_ref().is_some_and(|p|!p.active));}}
